typedef unsigned int nlUint32;
typedef unsigned int nslEmitterId;

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  nslEmitterId myId;
  char remainder[48];
};

struct nslSystem
{
  char beforeEmitterSlots[45120];
  nslEmitter emitterSlots[256];
  char beforeOn[56];
  bool on;
};

extern nslSystem nsl;
void _nslInitialized();
void _nslCheckEmitterIdValidity(nslEmitterId checkId);

#define NSL_SLOT_MASK 0x000003FF
#define NSL_GET_SLOT_FROM_ID( x ) ( x&NSL_SLOT_MASK )
#define ASSERT_EMITTER_ID_VALID(checkId) _nslCheckEmitterIdValidity(checkId)
#define ASSERT_NSL_INITIALIZED() _nslInitialized()

void nslSetEmitterAutoRelease( nslEmitterId emitterToSet )
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_EMITTER_ID_VALID(emitterToSet);
  nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToSet)].autoRelease = true;
}
